export function getGuideBySlug(slug: string): IGuidePost | undefined {
  return GUIDE_POSTS.find(
    (p) => p.slug.toLowerCase() === slug.toLowerCase()
  );
}

export function getGuidesByCategory(categorySlug: string): IGuidePost[] {
  return GUIDE_POSTS.filter(
    (p) => p.categorySlug.toLowerCase() === categorySlug.toLowerCase()
  );
}

export function getCategoryBySlug(slug: string): IGuideCategory | undefined {
  return GUIDE_CATEGORIES.find(
    (c) => c.slug.toLowerCase() === slug.toLowerCase()
  );
}

export function getRelatedGuides(slug: string, limit = 3): IGuidePost[] {
  const current = getGuideBySlug(slug);
  if (!current) return GUIDE_POSTS.slice(0, limit);
  return GUIDE_POSTS
    .filter((p) => p.slug !== slug && (p.categorySlug === current.categorySlug || p.categorySlug === "choosing-correct-riding-gear"))
    .slice(0, limit);
}
